/// Structured failure returned when a modeless authoring window cannot execute an MCP tool.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct AuthoringWindowMcpCallFailure {
    code: String,
    message: String,
}

impl AuthoringWindowMcpCallFailure {
    /// Stable diagnostic-style code for the failed invocation.
    pub fn code(&self) -> &str {
        &self.code
    }

    /// Human-readable failure description.
    pub fn message(&self) -> &str {
        &self.message
    }

    fn new(code: impl Into<String>, message: impl Into<String>) -> Self {
        Self {
            code: code.into(),
            message: message.into(),
        }
    }
}

fn mcp_authoring_permissions() -> AuthoringPermissions {
    AuthoringPermissions::read_only()
        .with(AuthoringPermission::Preview)
        .with(AuthoringPermission::ProjectDataWrite)
        .with(AuthoringPermission::AssetWrite)
}

